<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Analog Clock</title>
    <style>
        body {
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            background-color: white;
            margin: 0;
        }

        .clock {
            width: 200px;
            height: 200px;
            border: 1px solid black;
            position: relative;
            perspective: 1000px;
        }

        .clock::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 100%;
            height: 100%;
            border-radius: 50%;
            transform: translate(-50%, -50%);
            box-shadow: inset 0 0 0 100px white, 0 0 0 130px rgba(0, 0, 0, 0.1);
        }

        .clock .hour-hand,
        .clock .minute-hand,
        .clock .second-hand {
            position: absolute;
            top: 50%;
            left: 50%;
            transform-origin: 100% 100%;
            transition: transform 0.2s;
        }

        .clock .hour-hand {
            width: 8px;
            height: 50px;
            background: black;
            border-radius: 10px;
            transform: rotate(126deg) translate(-50%, -50%);
        }

        .clock .minute-hand {
            width: 6px;
            height: 70px;
            background: black;
            border-radius: 10px;
            transform: rotate(101.4deg) translate(-50%, -50%);
        }

        .clock .second-hand {
            width: 4px;
            height: 100px;
            background: red;
            border-radius: 10px;
            transform: rotate(282deg) translate(-50%, -50%);
        }

        .clock .numbers {
            display: flex;
            flex-direction: column;
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
        }

        .clock .numbers div {
            font-size: 14px;
            margin: 5px 0;
        }

        .clock .numbers div:nth-child(1) { transform: rotate(30deg); }
        .clock .numbers div:nth-child(2) { transform: rotate(60deg); }
        .clock .numbers div:nth-child(3) { transform: rotate(90deg); }
        .clock .numbers div:nth-child(4) { transform: rotate(120deg); }
        .clock .numbers div:nth-child(5) { transform: rotate(150deg); }
        .clock .numbers div:nth-child(6) { transform: rotate(180deg); }
        .clock .numbers div:nth-child(7) { transform: rotate(210deg); }
        .clock .numbers div:nth-child(8) { transform: rotate(240deg); }
        .clock .numbers div:nth-child(9) { transform: rotate(270deg); }
        .clock .numbers div:nth-child(10) { transform: rotate(300deg); }
        .clock .numbers div:nth-child(11) { transform: rotate(330deg); }
        .clock .numbers div:nth-child(12) { transform: rotate(360deg); }
    </style>
</head>
<body>
    <div class="clock">
        <div class="hour-hand"></div>
        <div class="minute-hand"></div>
        <div class="second-hand"></div>
        <div class="numbers">
            <div>12</div>
            <div>1</div>
            <div>2</div>
            <div>3</div>
            <div>4</div>
            <div>5</div>
            <div>6</div>
            <div>7</div>
            <div>8</div>
            <div>9</div>
            <div>10</div>
            <div>11</div>
        </div>
    </div>

    <script>
        setInterval(() => {
            const now = new Date();
            const seconds = now.getSeconds();
            const secondsHandAngle = (seconds / 60) * 360;
            const minutes = now.getMinutes();
            const minuteHandAngle = (minutes / 60) * 360 + (seconds / 60) * 6;
            const hours = now.getHours();
            const hourHandAngle = (hours / 12) * 360 + (minutes / 60) * 30;

            document.querySelector('.second-hand').style.transform = `rotate(${secondsHandAngle + 270}deg)`;
            document.querySelector('.minute-hand').style.transform = `rotate(${minuteHandAngle + 270}deg)`;
            document.querySelector('.hour-hand').style.transform = `rotate(${hourHandAngle + 270}deg)`;
        }, 1000);
    </script>
</body>
</html>
